public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Compute the serialized size of the message
    int size = schema.getSerializedSize(message);

    // Clear the buffer and serialize the message into it
    buffer.clear();
    schema.writeTo(buffer, message);
    byte[] bytes = buffer.toByteArray();

    // Write the length prefix (4 bytes, big-endian)
    out.write((size >>> 24) & 0xFF);
    out.write((size >>> 16) & 0xFF);
    out.write((size >>> 8) & 0xFF);
    out.write(size & 0xFF);

    // Write the serialized message bytes
    out.write(bytes);

    return size;
}

