private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (vertices.size() <= 1) {
        return true;
    }
    List<V> list = new ArrayList<>(vertices);
    int n = list.size();
    for (int i = 0; i < n; i++) {
        V v1 = list.get(i);
        for (int j = i + 1; j < n; j++) {
            V v2 = list.get(j);
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

