private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>();
    for (K keyObj : keys) {
        Integer key = (Integer) keyObj;
        Integer maxLower = null;
        for (K otherObj : keys) {
            Integer other = (Integer) otherObj;
            if (other < key && (maxLower == null || other > maxLower)) {
                maxLower = other;
            }
        }
        lowerBounds.add(maxLower != null ? maxLower : Integer.MIN_VALUE);
    }
    return lowerBounds;
}

